package com.rpsbattle.tournament;

import com.rpsbattle.tournament.coding.*;
import com.rpsbattle.tournament.domain.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

/** Reuses the HTTP coding fixture and its mocked sandbox; Docker is exercised separately. */
class TimelineDeadlineApiTest extends TimelineCodingApiTest {
 @Autowired CodingDeadlineService deadlines;
 @Autowired SubmissionStore submissions;
 @Autowired OwnedTournamentService ownedTournaments;
 @Autowired JdbcTemplate jdbc;
 String id(String base){return base.substring(base.lastIndexOf('/')+1);}
 Tournament tournament(String base){return tournaments.find(id(base));}
 String cupPolicy(boolean automatic)throws Exception{String base=cup("BOTH",true);var t=tournament(base);var tl=t.timeline;ownedTournaments.submissionMutation(t,com.rpsbattle.auth.AuthService.sessionAuthentication(account),()->{t.timeline=new TournamentTimeline(tl.registrationOpenAt(),tl.registrationCloseAt(),tl.codingOpenAt(),tl.codingCloseAt(),tl.validationStartAt(),tl.validationDeadline(),tl.checkInOpenAt(),tl.checkInCloseAt(),tl.tournamentStartAt(),tl.estimatedEndAt(),null,automatic?TournamentTimeline.DeadlinePolicy.AUTO_SUBMIT_LATEST_READY:TournamentTimeline.DeadlinePolicy.REQUIRE_EXPLICIT_SUBMIT);tournaments.changed(t);});when(clock.instant()).thenReturn(START.plusSeconds(125));return base;}
 com.fasterxml.jackson.databind.JsonNode ready(String base,int offset)throws Exception{var w=request(base+"/workspace","POST",Map.of("language","PYTHON"),200);w=request(base+"/workspace/me","PUT",Map.of("language","PYTHON","revision",w.path("revision").asLong(),"sourceCode","print('deadline source "+offset+"')\n"),200);request(base+"/workspace/me/build","POST",Map.of("language","PYTHON","revision",w.path("revision").asLong(),"sourceCode","print('deadline source "+offset+"')\n"),202);w=done(base);request(base+"/workspace/me/validate","POST",Map.of("language","PYTHON","revision",w.path("revision").asLong()),202);w=done(base);assertThat(w.path("status").asText()).isEqualTo("READY");jdbc.update("update tournament_submission_versions set created_at=?,updated_at=? where id=?",java.sql.Timestamp.from(START.plusSeconds(offset)),java.sql.Timestamp.from(START.plusSeconds(offset+1)),UUID.fromString(w.path("version").path("id").asText()));return w;}
 void submit(String base,com.fasterxml.jackson.databind.JsonNode w)throws Exception{request(base+"/workspace/me/submit","POST",Map.of("versionId",w.path("version").path("id").asText(),"rulesAccepted",true,"revision",request(base,"GET",null,200).path("revision").asLong()),200);jdbc.update("update tournament_bot_submissions set submitted_at=? where tournament_id=?",java.sql.Timestamp.from(START.plusSeconds(150)),UUID.fromString(id(base)));}
 com.fasterxml.jackson.databind.JsonNode freeze(String base)throws Exception{when(clock.instant()).thenReturn(START.plusSeconds(180));deadlines.processDeadlines();return request(base+"/participant-flow","GET",null,200);}
 @Test void defaultAutoSubmitsReadyAndPersistsOneImmutableDecisionAcrossRetries()throws Exception{
  String base=cupPolicy(true);var w=ready(base,130);var flow=freeze(base);var frozen=flow.path("frozenSubmission");assertThat(flow.path("submissionStatus").asText()).isEqualTo("SUBMISSION_FROZEN");assertThat(frozen.path("decision").asText()).isEqualTo("AUTO_SUBMITTED");assertThat(frozen.path("versionId").asText()).isEqualTo(w.path("version").path("id").asText());assertThat(frozen.path("sourceHash").asText()).isEqualTo(w.path("version").path("sourceHash").asText());assertThat(request(base+"/submission/me","GET",null,200).path("status").asText()).isEqualTo("LOCKED");
  long revision=tournament(base).revision;for(int i=0;i<3;i++)deadlines.processDeadlines();assertThat(tournament(base).revision).isEqualTo(revision);assertThat(request(base+"/participant-flow","GET",null,200).path("frozenSubmission")).isEqualTo(frozen);assertThat(jdbc.queryForObject("select count(*) from tournament_coding_freezes where tournament_id=?",Integer.class,UUID.fromString(id(base)))).isEqualTo(1);request(base+"/workspace/me","PUT",Map.of("language","PYTHON","revision",0,"sourceCode","late"),409);
 }
 @Test void explicitPolicyDoesNotAutoSubmitAndKeepsUnsavedReadySourceReadable()throws Exception{String base=cupPolicy(false);ready(base,130);var flow=freeze(base);assertThat(flow.path("submissionStatus").asText()).isEqualTo("SUBMISSION_MISSING");assertThat(flow.path("frozenSubmission").path("reason").asText()).isEqualTo("EXPLICIT_SUBMIT_REQUIRED");assertThat(flow.path("frozenSubmission").path("versionId").isNull()).isTrue();assertThat(request(base+"/workspace/me?language=PYTHON","GET",null,200).path("sourceCode").asText()).contains("deadline source");assertThat(request(base+"/submission/me","GET",null,200).path("status").asText()).isEqualTo("NO_SUBMISSION");}
 @Test void explicitSubmissionLocksAtTimelineDeadline()throws Exception{String base=cupPolicy(false);var w=ready(base,130);submit(base,w);var flow=freeze(base);assertThat(flow.path("frozenSubmission").path("decision").asText()).isEqualTo("EXPLICIT_SUBMIT");assertThat(request(base+"/submission/me","GET",null,200).path("status").asText()).isEqualTo("LOCKED");}
 @Test void newerReadyVersionReplacesPriorSubmissionWhenResubmissionAllowed()throws Exception{String base=cupPolicy(true);var first=ready(base,130);submit(base,first);var second=ready(base,155);var flow=freeze(base);assertThat(flow.path("frozenSubmission").path("versionId").asText()).isEqualTo(second.path("version").path("id").asText());assertThat(tournament(base).registrations).hasSize(1);}
 @Test void resubmitDisabledPreservesPreviouslySubmittedVersion()throws Exception{String base=cupPolicy(true);var tree=json.valueToTree(tournament(base).botPolicy);((com.fasterxml.jackson.databind.node.ObjectNode)tree).put("allowResubmitBeforeDeadline",false);var policy=json.treeToValue(tree,TournamentBotPolicy.class);ownedTournaments.submissionMutation(tournament(base),com.rpsbattle.auth.AuthService.sessionAuthentication(account),()->{tournament(base).botPolicy=policy;tournaments.changed(tournament(base));});var first=ready(base,130);submit(base,first);ready(base,155);assertThat(freeze(base).path("frozenSubmission").path("versionId").asText()).isEqualTo(first.path("version").path("id").asText());}
 @Test void unfinishedNewBuildCannotHideAnOlderReadyVersion()throws Exception{String base=cupPolicy(true);var first=ready(base,130);var second=ready(base,155);jdbc.update("update tournament_submission_versions set status='TEST_FAILED' where id=?",UUID.fromString(second.path("version").path("id").asText()));jdbc.update("update tournament_code_workspaces set status='TESTING' where id=?",UUID.fromString(second.path("id").asText()));assertThat(freeze(base).path("frozenSubmission").path("versionId").asText()).isEqualTo(first.path("version").path("id").asText());}
 @Test void readyCompletionAtOrAfterCutoffIsNeverAutoSubmittedEvenAfterDelayedScheduler()throws Exception{String base=cupPolicy(true);var w=ready(base,130);jdbc.update("update tournament_submission_versions set updated_at=? where id=?",java.sql.Timestamp.from(START.plusSeconds(180)),UUID.fromString(w.path("version").path("id").asText()));when(clock.instant()).thenReturn(START.plusSeconds(250));deadlines.processDeadlines();var flow=request(base+"/participant-flow","GET",null,200);assertThat(flow.path("submissionStatus").asText()).isEqualTo("SUBMISSION_MISSING");assertThat(flow.path("frozenSubmission").path("reason").asText()).isEqualTo("NO_READY_VERSION_BEFORE_DEADLINE");}
 @Test void integrityFailureRecordsMissingInsteadOfSubmittingAnAlteredArtifact()throws Exception{String base=cupPolicy(true);ready(base,130);doThrow(new WorkspaceSandbox.Failure("ARTIFACT_CHANGED")).when(sandbox).verify(any());assertThat(freeze(base).path("frozenSubmission").path("reason").asText()).isEqualTo("ARTIFACT_CHANGED");}
 @Test void atomicRollbackLeavesNoDecisionOrRosterAndRetryCanFinish()throws Exception{String base=cupPolicy(true);ready(base,130);var t=tournament(base);when(clock.instant()).thenReturn(START.plusSeconds(180));assertThatThrownBy(()->ownedTournaments.submissionMutation(t,null,()->{submissions.freezeAtDeadline(t,account.id().value(),true,clock.instant());throw new IllegalStateException("Simulated persistence failure");})).hasMessage("Simulated persistence failure");assertThat(submissions.frozenMine(t.id,account.id().value(),t.timeline.codingCloseAt())).isNull();assertThat(submissions.mine(t.id,account.id().value())).isNull();assertThat(t.registrations).isEmpty();assertThat(freeze(base).path("submissionStatus").asText()).isEqualTo("SUBMISSION_FROZEN");}
 @Test void pendingApplicationsNeverGetAutoSubmittedOrAFreezeDecision()throws Exception{String base=cup("BOTH",false);freeze(base);assertThat(submissions.pendingFreezeUsers(id(base),START.plusSeconds(180),25)).isEmpty();assertThat(request(base+"/participant-flow","GET",null,200).path("frozenSubmission").isNull()).isTrue();}
 @Test void noDeadlineDecisionIsCreatedEvenOneNanosecondBeforeClose()throws Exception{String base=cupPolicy(true);ready(base,130);when(clock.instant()).thenReturn(START.plusSeconds(180).minusNanos(1));deadlines.processDeadlines();assertThat(submissions.frozenMine(id(base),account.id().value(),START.plusSeconds(180))).isNull();assertThat(freeze(base).path("submissionStatus").asText()).isEqualTo("SUBMISSION_FROZEN");}
 @Test void existingSubmissionHashMustMatchTheSelectedImmutableVersion()throws Exception{String base=cupPolicy(false);var w=ready(base,130);submit(base,w);jdbc.update("update tournament_bot_submissions set artifact_hash=? where tournament_id=?","b".repeat(64),UUID.fromString(id(base)));assertThat(freeze(base).path("frozenSubmission").path("reason").asText()).isEqualTo("ARTIFACT_CHANGED");}
}
